import { create } from 'zustand';
import api from '../axiosConfig';

const useAuthStore = create((set, get) => ({
  user: null,
  isAuthenticated: false,
  error: null,
  loading: false,
  refreshingToken: false,
  
  login: async (username, password) => {
    set({ loading: true, error: null });
    try {
      // Llamada real al endpoint JWT de Django
      const response = await api.post('/auth/token/', { username, password });
      
      const { access, refresh } = response.data;
      
      localStorage.setItem('access_token', access);
      localStorage.setItem('refresh_token', refresh);
      
      set({ user: { username }, isAuthenticated: true, loading: false });
      return true;
    } catch (err) {
      set({ 
        error: err.response?.data?.detail || 'Credenciales inválidas', 
        loading: false 
      });
      return false;
    }
  },
  
  register: async (userData) => {
    set({ loading: true, error: null });
    try {
      await api.post('/auth/register/', userData);
      
      // Auto-login después de registro exitoso
      const response = await api.post('/auth/token/', { 
        username: userData.username, 
        password: userData.password 
      });
      
      const { access, refresh } = response.data;
      localStorage.setItem('access_token', access);
      localStorage.setItem('refresh_token', refresh);
      
      set({ user: { username: userData.username }, isAuthenticated: true, loading: false });
      return true;
    } catch (err) {
      const errorMsg = err.response?.data?.username?.[0] || err.response?.data?.detail || 'Error al registrar usuario';
      set({ error: errorMsg, loading: false });
      return false;
    }
  },

  
  logout: () => {
    localStorage.removeItem('access_token');
    localStorage.removeItem('refresh_token');
    set({ user: null, isAuthenticated: false, error: null });
  },
  
  checkAuth: async () => {
    const token = localStorage.getItem('access_token');
    if (!token) {
      set({ isAuthenticated: false, user: null });
      return;
    }
    try {
      const response = await api.get('/auth/perfil/');
      set({ user: response.data, isAuthenticated: true });
    } catch (err) {
      // Intentar refrescar el token antes de cerrar sesión
      const refreshToken = localStorage.getItem('refresh_token');
      if (refreshToken) {
        try {
          const refreshResponse = await api.post('/auth/token/refresh/', { 
            refresh: refreshToken 
          });
          const { access } = refreshResponse.data;
