  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 1rem;
  color: #fff;
  box-shadow: 0 0 12px rgba(0, 240, 255, 0.2);
}

.sidebar-user-info {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.sidebar-user-name {
  font-size: 0.9rem;
  font-weight: 600;
  color: #fff;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.sidebar-user-role {
  font-size: 0.7rem;
  color: rgba(0, 240, 255, 0.6);
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

/* Sidebar Nav */
.sidebar-nav {
  flex: 1;
