  padding: 0.8rem 0.8rem;
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
}

.nav-section-title {
  font-size: 0.65rem;
  font-weight: 600;
  color: rgba(255,255,255,0.25);
  text-transform: uppercase;
  letter-spacing: 1.5px;
  padding: 0.8rem 0.8rem 0.4rem;
  margin-top: 0.5rem;
}

.nav-section-title:first-child {
  margin-top: 0;
}

.nav-item {
