  color: rgba(255,255,255,0.25);
}

/* Filter Select */
.filter-select {
  background: rgba(0, 0, 0, 0.3);
  border: 1px solid rgba(0, 240, 255, 0.15);
  border-radius: 8px;
  padding: 0.6rem 1rem;
  color: rgba(255,255,255,0.7);
  font-size: 0.85rem;
  outline: none;
  cursor: pointer;
}

.filter-select:focus {
  border-color: rgba(0, 240, 255, 0.4);
}

/* Status Badge */
.status-badge {
  display: inline-flex;
  align-items: center;
